/* Azimuthal equidistant projection: the spherical formulas, a fixture generated by
   an independent Python reference that places the point from the c/sin(c) terms and
   reads the azimuth back off the easting, the catalog cases, the identities that
   follow from the definition and the page contract. No expected number comes from
   the page itself. */
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const assert = require('node:assert/strict');

const root = path.resolve(__dirname, '..');
const slug = 'azimuthal-equidistant-projection';
const html = fs.readFileSync(path.join(root, 'frontend/tools', slug, 'index.html'), 'utf8');
const startMarker = '/* aeqd-core:start */';
const endMarker = '/* aeqd-core:end */';
const start = html.indexOf(startMarker);
const end = html.indexOf(endMarker);
assert.ok(start > -1 && end > start, 'core markers missing');
const coreSource = html.slice(start, end + endMarker.length);
assert.ok(!/document\.|window\./.test(coreSource), 'the core stays free of DOM access');
const sandbox = { module: {} };
vm.createContext(sandbox);
vm.runInContext(coreSource + '\nmodule.exports = AeqdCore;', sandbox);
const C = sandbox.module.exports;

const DEG = Math.PI / 180;
const near = (actual, expected, label, relative) => {
  const rel = relative === undefined ? 1e-9 : relative;
  assert.ok(Number.isFinite(actual), label + ': ' + actual + ' is not a finite number');
  assert.ok(Math.abs(actual - expected) <= rel * Math.max(1, Math.abs(expected)),
    label + ': ' + actual + ' is not within ' + rel + ' of ' + expected);
};
const sameAngle = (actual, expected, label) => {
  const difference = Math.abs(((actual - expected) % 360 + 540) % 360 - 180);
  assert.ok(difference <= 1e-9, label + ': ' + actual + ' is not ' + expected + ' degrees');
};
const failure = (input) => {
  try { C.analyze(input); } catch (error) { return error.message; }
  return null;
};
const base = { centreLatitude: '51.5074', centreLongitude: '-0.1278', latitude: '40.7128', longitude: '-74.006' };

// ---- Constants and parsing.
assert.equal(C.EARTH_RADIUS, 6371.0088);
assert.equal(C.LIMITS.latitude, 90);
assert.equal(C.LIMITS.longitude, 180);
assert.equal(C.BANDS.minimal, 10000);
assert.equal(C.BANDS.moderate, 15000);
assert.equal(failure({ ...base, centreLatitude: '' }), 'Enter the centre latitude.');
assert.equal(failure({ ...base, latitude: 'North' }), 'Point latitude must be a number.');
assert.equal(failure({ ...base, longitude: '1e2' }), 'Point longitude must be a number.');
assert.equal(failure({ ...base, latitude: '90.5' }), 'Point latitude must be between -90 and 90 degrees.');
assert.equal(C.analyze({ ...base, centreLatitude: '51,5074' }).centreLatitude, 51.5074, 'a comma is a decimal mark');
assert.equal(C.analyze({ ...base, latitude: '+40.7128' }).latitude, 40.7128, 'a leading plus is accepted');

// ---- The independent Python fixture: 40 projections over every corner of the sphere.
const fixture = JSON.parse(fs.readFileSync(path.join(root, 'tests/fixtures/azimuthal_equidistant_vectors.json'), 'utf8'));
assert.ok(fixture.vectors.length >= 40, 'fixture size');
assert.equal(fixture.cases.length, 20, 'fixture carries the catalog cases');
for (const vector of fixture.vectors) {
  const label = vector.name;
  const result = C.analyze(vector.input);
  const expected = vector.expected;
  near(result.distance, expected.distance, label + ' distance');
  near(result.angularDistance, expected.angularDistance, label + ' angular distance');
  near(result.deltaLongitude, expected.deltaLongitude, label + ' delta longitude');
  assert.equal(result.band, expected.band, label + ' band');
  assert.equal(result.antipode, expected.antipode, label + ' antipode flag');
  assert.equal(result.sameAsCentre, expected.sameAsCentre, label + ' centre flag');
  if (expected.easting === null) {
    assert.equal(result.easting, null, label + ' easting is undefined');
    assert.equal(result.northing, null, label + ' northing is undefined');
    assert.equal(result.azimuth, null, label + ' azimuth is undefined');
    assert.equal(result.tangentialScale, null, label + ' tangential scale is unbounded');
    assert.equal(result.stretch, null, label + ' stretch is unbounded');
    continue;
  }
  near(result.easting, expected.easting, label + ' easting');
  near(result.northing, expected.northing, label + ' northing');
  near(result.radialScale, 1, label + ' radial scale');
  near(result.tangentialScale, expected.tangentialScale, label + ' tangential scale');
  near(result.stretch, expected.stretch, label + ' stretch');
  if (expected.azimuth === null) {
    assert.equal(result.azimuth, null, label + ' azimuth is undefined at the centre');
  } else {
    sameAngle(result.azimuth, expected.azimuth, label + ' azimuth');
  }
}

// ---- The catalog cases, replayed through the documented input shape.
const catalog = JSON.parse(fs.readFileSync(path.join(root, 'frontend/assets/tool-catalog.json'), 'utf8'));
const matches = catalog.tools.filter((tool) => tool.slug === slug);
assert.equal(matches.length, 1, 'slug must exist exactly once');
const entry = matches[0];
assert.equal(entry.name, 'Azimuthal Equidistant Projection Calculator');
assert.equal(entry.category, 'Geography');
assert.equal(entry.subcategory, 'Coordinates');
assert.equal(entry.risk, 'low');
assert.equal(entry.maturity, 'draft');
assert.equal(entry.reviewedAt, null);
assert.equal(entry.listed, true);
assert.equal(entry.legacyCategory, null);
assert.equal(entry.icon, '\u{1F310}');
assert.equal(new Set(entry.tags).size, entry.tags.length, 'duplicate tags');
assert.equal(new Set(entry.aliases).size, entry.aliases.length, 'duplicate aliases');
assert.ok(entry.method.length > 800, 'method must document the formulas, the bands and the limits');
assert.equal(entry.sources.length, 1);
assert.ok(entry.sources[0].url.startsWith('https://en.wikipedia.org/wiki/Azimuthal_equidistant_projection'), 'source url');
assert.ok(entry.sources[0].title.includes('Azimuthal equidistant projection'), 'source title names the projection');
assert.equal(entry.testCases.length, 20, 'catalog case count');
assert.equal(entry.testCases.filter((testCase) => testCase.kind === 'golden').length, 7);
assert.equal(entry.testCases.filter((testCase) => testCase.kind === 'boundary').length, 3);
assert.equal(entry.testCases.filter((testCase) => testCase.kind === 'validation').length, 10);

const publicCount = catalog.tools.filter((tool) => tool.listed).length;
assert.ok(publicCount >= 2066, 'the catalog keeps growing: ' + publicCount);
assert.deepEqual(entry.testCases, fixture.cases, 'the catalog cases are the fixture cases');

for (const testCase of entry.testCases) {
  if (testCase.kind === 'validation') {
    assert.equal(failure(testCase.input), testCase.expectedError, testCase.name);
    continue;
  }
  const result = C.analyze(testCase.input);
  for (const [field, expected] of Object.entries(testCase.expected)) {
    if (expected === null) {
      assert.equal(result[field], null, testCase.name + ' ' + field);
    } else if (typeof expected === 'string' || typeof expected === 'boolean') {
      assert.equal(result[field], expected, testCase.name + ' ' + field);
    } else if (field === 'azimuth') {
      sameAngle(result[field], expected, testCase.name + ' ' + field);
    } else {
      near(result[field], expected, testCase.name + ' ' + field);
    }
  }
}

// ---- Identities that follow from the definition itself.
const r = C.analyze(base);
near(r.distance, C.EARTH_RADIUS * r.angularDistance * DEG, 'distance is radius times angular distance');
near(Math.hypot(r.easting, r.northing), r.distance, 'the plotted point is the whole distance from the centre');
near(r.radialScale, 1, 'the radial scale is exactly one');
near(r.tangentialScale, (r.angularDistance * DEG) / Math.sin(r.angularDistance * DEG), 'tangential scale is c over sin c');
assert.ok(r.tangentialScale > 1, 'the tangential scale stretches away from the centre');
assert.ok(r.easting < 0 && r.northing > 0, 'New York is west and north of London');
near(r.azimuth, 288.3297015936, 'the London to New York great-circle bearing', 1e-9);

// The same geometry, read from the bearing formula alone.
const bearing = (input) => {
  const phi1 = Number(input.centreLatitude) * DEG;
  const phi = Number(input.latitude) * DEG;
  const lambda = (((Number(input.longitude) - Number(input.centreLongitude)) % 360 + 540) % 360 - 180) * DEG;
  return (Math.atan2(Math.sin(lambda) * Math.cos(phi),
    Math.cos(phi1) * Math.sin(phi) - Math.sin(phi1) * Math.cos(phi) * Math.cos(lambda)) / DEG + 360) % 360;
};
sameAngle(r.azimuth, bearing(base), 'the azimuth is the initial great-circle bearing');

// Due east on the equator is exactly east, due north on a meridian is exactly north.
const east = C.analyze({ centreLatitude: '0', centreLongitude: '0', latitude: '0', longitude: '30' });
near(east.azimuth, 90, 'a point on the equator to the east', 1e-12);
near(east.northing, 0, 'no northing due east on the equator', 1e-9);
near(east.easting, east.distance, 'the whole distance is easting', 1e-9);
const north = C.analyze({ centreLatitude: '10', centreLongitude: '20', latitude: '60', longitude: '20' });
near(north.azimuth, 0, 'a point due north', 1e-12);
near(north.easting, 0, 'no easting due north', 1e-9);
near(north.northing, north.distance, 'the whole distance is northing', 1e-9);

// The antipode keeps the distance and drops the direction.
const antipode = C.analyze({ centreLatitude: '10', centreLongitude: '20', latitude: '-10', longitude: '-160' });
near(antipode.distance, Math.PI * C.EARTH_RADIUS, 'half the circumference to the antipode', 1e-12);
assert.equal(antipode.easting, null);
assert.equal(antipode.northing, null);
assert.equal(antipode.azimuth, null);
assert.equal(antipode.tangentialScale, null);
assert.equal(antipode.antipode, true);
assert.equal(antipode.band, 'severe');
const nearly = C.analyze({ centreLatitude: '0', centreLongitude: '0', latitude: '0', longitude: '179.99' });
assert.equal(nearly.antipode, false, 'a point a kilometre short of the antipode is not the antipode');
assert.ok(nearly.tangentialScale > 1000, 'the scale is enormous near the antipode');

// The centre itself: no distance, no direction, no stretching.
const centre = C.analyze({ centreLatitude: '-12.5', centreLongitude: '130.8', latitude: '-12.5', longitude: '130.8' });
assert.equal(centre.distance, 0);
assert.equal(centre.easting, 0);
assert.equal(centre.northing, 0);
assert.equal(centre.azimuth, null);
assert.equal(centre.tangentialScale, 1);
assert.equal(centre.band, 'centre');
assert.equal(centre.sameAsCentre, true);

// Distance is symmetric and the antimeridian is not a special case.
const there = C.analyze({ centreLatitude: '35', centreLongitude: '139', latitude: '-33', longitude: '18' });
const back = C.analyze({ centreLatitude: '-33', centreLongitude: '18', latitude: '35', longitude: '139' });
near(there.distance, back.distance, 'distance is symmetric');
const across = C.analyze({ centreLatitude: '0', centreLongitude: '179.5', latitude: '0', longitude: '-179.5' });
const sameAcross = C.analyze({ centreLatitude: '0', centreLongitude: '-179.5', latitude: '0', longitude: '179.5' });
near(across.distance, sameAcross.distance, 'the antimeridian reads the same either way');
near(across.distance, C.EARTH_RADIUS * DEG, 'one degree across the antimeridian', 1e-9);
near(across.deltaLongitude, 1, 'the wrapped change of longitude');

// A polar centre collapses to rho = R (90 - phi) and the colatitude distance.
const polar = C.analyze({ centreLatitude: '90', centreLongitude: '0', latitude: '35', longitude: '77' });
near(polar.distance, C.EARTH_RADIUS * 55 * DEG, 'the distance from the pole is the colatitude', 1e-9);
near(Math.hypot(polar.easting, polar.northing), polar.distance, 'the polar point keeps its distance');

// The tangential scale grows monotonically with distance and the bands follow it.
let previousScale = 0;
let previousBand = 'minimal';
const order = ['minimal', 'moderate', 'severe'];
for (const distanceKm of [100, 1000, 5000, 9000, 11000, 14000, 18000]) {
  const result = C.analyze({ centreLatitude: '0', centreLongitude: '0', latitude: '0', longitude: String(distanceKm / C.EARTH_RADIUS / DEG) });
  assert.ok(result.tangentialScale > previousScale, 'the tangential scale grows with distance');
  previousScale = result.tangentialScale;
  assert.ok(order.indexOf(result.band) >= order.indexOf(previousBand), 'the band never softens with distance');
  previousBand = result.band;
}
assert.equal(C.analyze({ centreLatitude: '0', centreLongitude: '0', latitude: '0', longitude: '0' }).band, 'centre');
assert.equal(C.analyze({ centreLatitude: '0', centreLongitude: '0', latitude: '0', longitude: '100' }).band, 'moderate');
assert.equal(C.analyze({ centreLatitude: '0', centreLongitude: '0', latitude: '0', longitude: '150' }).band, 'severe');

// ---- Page contract: shared shell, accessible controls, no runtime foreign APIs.
assert.ok(!/fetch\(|XMLHttpRequest|localStorage|sessionStorage|indexedDB|WebSocket/.test(html), 'network or storage API found');
assert.ok(!/<script[^>]+src="https?:/i.test(html), 'remote script');
assert.ok(!/<link[^>]+href="https?:/i.test(html), 'remote stylesheet');
assert.ok(!/on(?:click|input|change|submit)=/i.test(html), 'inline handler');
assert.ok(!/\beval\s*\(|new\s+Function\b/.test(html), 'unsafe script evaluation');
assert.ok(html.includes('<form id="aeqd-form" novalidate>'), 'form missing');
assert.ok(html.includes('type="submit"'), 'submit missing');
assert.ok(html.includes('role="alert"'), 'error announcement missing');
assert.ok(html.includes('aria-live="polite" aria-atomic="true"'), 'result region missing');
assert.ok(html.includes('/assets/app.js') && html.includes('/assets/style.css'), 'shared shell assets missing');
for (const id of ['centre-latitude', 'centre-longitude', 'latitude', 'longitude']) {
  assert.ok(html.includes('for="' + id + '"'), 'missing label for ' + id);
  assert.ok(html.includes('id="' + id + '"'), 'missing control ' + id);
}
for (const id of ['aeqd-form', 'aeqd-err', 'aeqd-out', 'note', 'reset']) {
  assert.ok(html.includes('id="' + id + '"'), 'missing id ' + id);
}
assert.ok(!/style="[^"]*width:\s*\d{3,}px/.test(html), 'fixed wide inline styles');

console.log('azimuthal-equidistant: 20 catalog cases, ' + fixture.vectors.length +
  ' reference vectors, identities, bands and page contracts passed');
